163→        let prompts = vec![
164→            make_prompt("key1", Some("default1")),
165→            make_prompt("key2", Some("default2")),
166→        ];
167→        let mut env = HashMap::new();
168→        env.insert("BIVVY_PROMPT_KEY2".to_string(), "override2".to_string());
169→
170→        let values = PreflightCollector::collect_non_interactive(&prompts, &env).unwrap();
171→
172→        assert_eq!(values.get("key1"), Some(&"default1".to_string()));
173→        assert_eq!(values.get("key2"), Some(&"override2".to_string()));
174→    }
175→}
