274→                                                '2' => Ok(Key::Insert),
275→                                                '3' => Ok(Key::Del),
276→                                                '4' => Ok(Key::End), // tmux
277→                                                '5' => Ok(Key::PageUp),
278→                                                '6' => Ok(Key::PageDown),
279→                                                '7' => Ok(Key::Home), // xrvt
280→                                                '8' => Ok(Key::End),  // xrvt
