404→fn make_raw(termios: &mut libc::termios) {
405→    // This is the manual implementation for QNX, which does not have cfmakeraw.
406→    termios.c_iflag &= !(libc::IGNBRK
407→        | libc::BRKINT
408→        | libc::PARMRK
409→        | libc::ISTRIP
410→        | libc::INLCR
411→        | libc::IGNCR
412→        | libc::ICRNL
413→        | libc::IXON);
414→    termios.c_oflag &= !libc::OPOST;
415→    termios.c_lflag &= !(libc::ECHO | libc::ECHONL | libc::ICANON | libc::ISIG | libc::IEXTEN);
416→    termios.c_cflag &= !(libc::CSIZE | libc::PARENB);
417→    termios.c_cflag |= libc::CS8;
418→}
