420→// This version will be compiled for all targets that are NOT QNX.
421→#[cfg(not(target_os = "nto"))]
422→fn make_raw(termios: &mut libc::termios) {
423→    // For other systems (Linux, macOS, BSD, etc.), use the standard libc call.
424→    unsafe { libc::cfmakeraw(termios) };
