524→
525→    /// Make the cursor visible again.
526→    #[inline]
527→    pub fn show_cursor(&self) -> io::Result<()> {
528→        show_cursor(self)
529→    }
530→
531→    /// Hide the cursor.
532→    #[inline]
533→    pub fn hide_cursor(&self) -> io::Result<()> {
534→        hide_cursor(self)
535→    }
